'use strict';

// MODULES //

var numelDimension = require( '@stdlib/ndarray/base/numel-dimension' );
var getStride = require( '@stdlib/ndarray/base/stride' );
var getOffset = require( '@stdlib/ndarray/base/offset' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );
var strided = require( '@stdlib/blas/base/strsv' ).ndarray;


// MAIN //

/**
* Solves one of the systems of equations `A*x = b` or `A^T*x = b` where `b` and `x` are `N` element ndarrays and `A` is an `N` by `N` unit, or non-unit, upper or lower triangular matrix.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a two-dimensional input ndarray.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {Object} output ndarray
*
* @example
* var Float32Vector = require( '@stdlib/ndarray/vector/float32' );
* var ndarray = require( '@stdlib/ndarray/base/ctor' );
* var Float32Array = require( '@stdlib/array/float32' );
*
* var x = new Float32Vector( [ 1.0, 2.0, 3.0 ] );
* var A = new ndarray( 'float32', new Float32Array( [ 1.0, 2.0, 3.0, 0.0, 4.0, 5.0, 0.0, 0.0, 6.0 ] ), [ 3, 3 ], [ 3, 1 ], 0, 'row-major' );
*
* var out = strsv( [ x, A ] );
* // returns <ndarray>[ -0.25, -0.125, 0.5 ]
*
* var bool = ( out === x );
* // returns true
*/
function strsv( arrays ) {
	var x = arrays[ 0 ];
	var A = arrays[ 1 ];
	strided( 'upper', 'no-transpose', 'non-unit', numelDimension( A, 0 ), getData( A ), getStride( A, 0 ), getStride( A, 1 ), getOffset( A ), getData( x ), getStride( x, 0 ), getOffset( x ) );
	return x;
}


// EXPORTS //

module.exports = strsv;
